import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(useGSAP);

export function Timeline() {
  const container = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      const tl = gsap.timeline({ defaults: { duration: {{duration}}, ease: "{{ease}}" } });

      tl.from(".title", { y: 40, opacity: 0 })
        .from(".subtitle", { y: 20, opacity: 0 }, "-={{overlap}}")
        .from(".cta", { scale: 0.8, opacity: 0 }, "-={{overlap}}");
    },
    { scope: container },
  );

  return (
    <section ref={container}>
      <h1 className="title">Build faster</h1>
      <p className="subtitle">Everything in one place.</p>
      <button className="cta">Get started</button>
    </section>
  );
}
